      "id": "arxiv:2609.11877v1",
      "title": "Biology-in-the-loop: Amortized Adaptive Hit Discovery in CRISPR Screens",
      "url": "https://arxiv.org/abs/2609.11877v1",
      "pdfUrl": "https://arxiv.org/pdf/2609.11877v1",
      "source": "arXiv",
