      "id": "49657850",
      "title": "Ask HN: Can we please limit the AI news flood?",
      "url": "https://news.ycombinator.com/item?id=49657850",
      "hnUrl": "https://news.ycombinator.com/item?id=49657850",
      "source": "Hacker News",
