        "id": "arxiv:2609.11737v1",
        "title": "ORCH: Organizational Principles Enable Collective Intelligence in Embodied AI",
        "url": "https://arxiv.org/abs/2609.11737v1",
        "pdfUrl": "https://arxiv.org/pdf/2609.11737v1",
